import{Z as e,e as t,f as o,a0 as i}from"./chunks/framework.DmpHOl9T.js";const c=JSON.parse('{"title":"Submission Statuses","description":"","frontmatter":{},"headers":[],"relativePath":"submissions/submission-statuses.md","filePath":"submissions/submission-statuses.md","lastUpdated":null}'),a={name:"submissions/submission-statuses.md"};function n(r,s,l,u,m,d){return t(),o("div",null,[...s[0]||(s[0]=[i('<h1 id="submission-statuses" tabindex="-1">Submission Statuses <a class="header-anchor" href="#submission-statuses" aria-label="Permalink to &quot;Submission Statuses&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For statuses combined with form conditions and post-submit routing, see <a href="/guides/submissions-workflows/submission-statuses-and-conditional-workflows">Submission statuses and conditional workflows</a>.</p></div><p>Statuses are labels you can use to organise and manage submissions after they have been saved.</p><p>They are useful when “new submission” is not enough detail for your team’s workflow.</p><p>Typical examples are:</p><ul><li><code>new</code></li><li><code>in-progress</code></li><li><code>approved</code></li><li><code>closed</code></li></ul><p>This gives teams a simple workflow around submissions without changing the form itself.</p><p>Each form can choose a default status for new submissions, and optional <strong>submission status rules</strong> that change the status on <strong>final submit</strong> or <strong>every page</strong>.</p><p>That means different forms can enter your process in different states, depending on how they are handled internally.</p><p>Enable rules under the form’s <strong>Submissions</strong> settings. Rules run in order; the first match wins. Optional conditions can limit a rule to certain answers. For module code when a rule cannot be expressed per form, see <a href="/guides/submissions-workflows/run-custom-code-on-page-submit-or-form-submit">Run custom code on page submit or form submit</a>.</p><p>Statuses are separate from whether a submission is:</p><ul><li>complete</li><li>incomplete</li><li>spam</li></ul><p>Those are system states. A status is your workflow label on top of that.</p><p>Statuses are managed in Formie settings under <strong>Submission Statuses</strong>.</p><p>Each status has:</p><ul><li>a name</li><li>a handle</li><li>a colour</li><li>an optional description</li></ul><p>One status can be marked as the default.</p><ul><li>You cannot delete the default status while it is the default.</li><li>A status that is still in use by submissions cannot be freely removed.</li><li>Statuses are stored in project config, so they can travel with the project like other shared settings.</li></ul><p>Add statuses when a team actually needs them for review or follow-up.</p><p>If every submission is handled the same way, the default status may be all you need.</p>',20)])])}const h=e(a,[["render",n]]);export{c as __pageData,h as default};
